$(window).resize(function(){
  // DataTables can preInit (and fire this via $(window).resize() below) before
  // base_plugin.html's initVariables() has run - nothing to size yet.
  if (!window.pageLength)
    return;
  let tab = $('#resize_wrapper > div.tab-pane.active').attr('id');
  // window.pageLength is keyed by table id, not tab id - a tab can host more than one table
  // (see base_plugin.html), so this wrapper-height adjustment (shared by every table in the
  // tab) is worth doing if ANY of them is currently in auto mode, not just a single one.
  let anyAuto = $('#' + tab + ' table.dataTable').toArray().some(
    t => (window.pageLength[t.id] || {}).pagelength == 1
  );
  if (!anyAuto)
    return;
  additional = 0;

  if ( $( "#resize_wrapper > div#" + tab + ">div.mb-2" ).length ){
    $("#resize_wrapper > div#" + tab).find('div.mb-2').filter(':visible').each(function(){
    additional += $(this).outerHeight(true);
    });
  }
  else if ( $( "#resize_wrapper > div#" + tab + ">div>div.mb-2" ).length ){
    $("#resize_wrapper > div#" + tab + ">div").find('div.mb-2').filter(':visible').each(function(){
    additional += $(this).outerHeight(true);
    });
  }
  if ( $( "#resize_wrapper").length){
  $('#resize_wrapper').css('height', $(window).height() - $('#resize_wrapper').offset().top - additional - 15 - window.toggle);
  }
});

